const body = $json.body;
const headers = $json.headers ?? {};
const required = ['schema_version', 'case_id', 'case_reference', 'case_version', 'trigger_event'];
const bodyIsObject = body !== null && typeof body === 'object' && !Array.isArray(body);
const keys = bodyIsObject ? Object.keys(body).sort() : [];
const valid = bodyIsObject
  && JSON.stringify(keys) === JSON.stringify([...required].sort())
  && body.schema_version === '1'
  && /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(body.case_id)
  && /^CASE-[0-9]{4}-[0-9]{4,}$/.test(body.case_reference)
  && body.case_version === 1
  && body.trigger_event === 'CASE_RECEIVED'
  && /^[0-9a-f]{64}$/.test(headers['idempotency-key'] ?? '');
if (!valid) {
  return {
    json: {
      valid: false,
      response_status: 422,
      response_body: {
        error_code: 'INVALID_WORKFLOW_START',
        message: 'The request does not match the workflow-start contract.',
        retryable: false
      }
    }
  };
}
return {
  json: {
    valid: true,
    case_id: body.case_id,
    idempotency_key: headers['idempotency-key'],
    primary_body: {
      schema_version: body.schema_version,
      case_reference: body.case_reference,
      expected_case_version: body.case_version,
      trigger_event: body.trigger_event
    }
  }
};

function asObject(value) {
  if (typeof value === 'string') {
    try {
      value = JSON.parse(value);
    } catch {
      return null;
    }
  }
  return value !== null && typeof value === 'object' && !Array.isArray(value)
    ? value
    : null;
}

function distinctObjects(values) {
  return values.filter((value, index) =>
    value !== null && values.indexOf(value) === index
  );
}

function isSuccessBody(value) {
  return value.schema_version === '1'
    && value.status === 'ACCEPTED'
    && typeof value.workflow_start_reference === 'string'
    && value.workflow_start_reference.trim().length > 0
    && value.workflow_start_reference.length <= 100
    && typeof value.case_reference === 'string'
    && /^CASE-[0-9]{4}-[0-9]{4,}$/.test(value.case_reference)
    && value.accepted_transition === 'RECEIVED->ANALYZING'
    && ['ANALYZING', 'NEEDS_INFORMATION', 'NEEDS_REVIEW', 'PENDING_APPROVAL', 'READY_FOR_ACTION', 'COMPLETED', 'REJECTED', 'FAILED'].includes(value.current_state)
    && Number.isInteger(value.case_version)
    && value.case_version >= 2
    && typeof value.idempotent_replay === 'boolean';
}

function isErrorBody(value) {
  return typeof value.error_code === 'string'
    && value.error_code.trim().length > 0
    && typeof value.message === 'string'
    && value.message.trim().length > 0
    && typeof value.retryable === 'boolean';
}

function keysOf(value) {
  try {
    return value === null ? [] : Object.keys(value).slice(0, 12);
  } catch {
    return ['unavailable'];
  }
}

const suppliedStatus = $json.response_status ?? $json.statusCode;
const suppliedBody = $json.response_body ?? $json.body;
const responseStatus = Number(suppliedStatus);
const rootBody = asObject(suppliedBody);
const candidates = distinctObjects([
  rootBody,
  asObject(rootBody?.body),
  asObject(rootBody?.data),
  asObject(rootBody?.response),
  asObject(rootBody?.json),
  asObject($json.data),
  asObject($json.response),
  asObject($json)
]);
const successBody = candidates.find(isSuccessBody);
const validatedIntent = $('Validate v1 Intent').item.json;

if (responseStatus === 200 && successBody) {
  const responseBody = {
    schema_version: successBody.schema_version,
    status: successBody.status,
    workflow_start_reference: successBody.workflow_start_reference,
    case_reference: successBody.case_reference,
    accepted_transition: successBody.accepted_transition,
    current_state: successBody.current_state,
    case_version: successBody.case_version,
    idempotent_replay: successBody.idempotent_replay
  };
  return {
    json: {
      response_status: 200,
      response_body_json: JSON.stringify(responseBody),
      continuation: {
        case_id: validatedIntent.case_id,
        case_reference: successBody.case_reference,
        expected_case_version: 2,
        workflow_start_reference: successBody.workflow_start_reference
      }
    }
  };
}

const statusIsValid = Number.isInteger(responseStatus)
  && responseStatus >= 100
  && responseStatus <= 599;
if (!statusIsValid || responseStatus === 200) {
  return {
    json: {
      response_status: 502,
      response_body_json: JSON.stringify({
        error_code: 'INVALID_PRIMARY_RESPONSE',
        message: 'The primary workflow response did not match the v1 acknowledgement contract.',
        retryable: true,
        received_shape: {
          item_keys: keysOf(asObject($json)),
          body_keys: keysOf(rootBody)
        }
      })
    }
  };
}

const errorBody = candidates.find(isErrorBody);
const responseBody = errorBody
  ? {
      error_code: errorBody.error_code,
      message: errorBody.message,
      retryable: errorBody.retryable
    }
  : {
      error_code: `PRIMARY_HTTP_${responseStatus}`,
      message: 'The primary workflow endpoint returned a non-contract error.',
      retryable: responseStatus === 408
        || responseStatus === 429
        || responseStatus >= 500
    };
return {
  json: {
    response_status: responseStatus,
    response_body_json: JSON.stringify(responseBody)
  }
};

function asObject(value) {
  if (typeof value === 'string') {
    try {
      value = JSON.parse(value);
    } catch {
      return null;
    }
  }
  return value !== null && typeof value === 'object' && !Array.isArray(value)
    ? value
    : null;
}

function distinctObjects(values) {
  return values.filter((value, index) =>
    value !== null && values.indexOf(value) === index
  );
}

function hasExactKeys(value, required) {
  return JSON.stringify(Object.keys(value).sort())
    === JSON.stringify([...required].sort());
}

const analysisKeys = [
  'schema_version',
  'analysis_run_id',
  'case_reference',
  'attempt_number',
  'outcome',
  'analysis_status',
  'validation_decision',
  'current_state',
  'case_version',
  'idempotent_replay',
  'provider_called'
];
const outcomes = [
  'READY',
  'NEEDS_INFORMATION',
  'NEEDS_REVIEW',
  'REJECTED',
  'FAILED',
  'RETRYABLE_FAILURE',
  'REPLAY'
];
const analysisStatuses = [
  'COMPLETED',
  'INVALID_OUTPUT',
  'FAILED',
  'SKIPPED'
];
const decisions = [
  null,
  'READY',
  'NEEDS_INFORMATION',
  'NEEDS_REVIEW',
  'REJECTED'
];
const states = [
  'ANALYZING',
  'NEEDS_INFORMATION',
  'NEEDS_REVIEW',
  'PENDING_APPROVAL',
  'READY_FOR_ACTION',
  'COMPLETED',
  'REJECTED',
  'FAILED'
];

function isAnalysisBody(value) {
  return hasExactKeys(value, analysisKeys)
    && value.schema_version === '1'
    && /^[0-9a-f]{8}-[0-9a-f]{4}-[1-5][0-9a-f]{3}-[89ab][0-9a-f]{3}-[0-9a-f]{12}$/.test(value.analysis_run_id)
    && /^CASE-[0-9]{4}-[0-9]{4,}$/.test(value.case_reference)
    && Number.isInteger(value.attempt_number)
    && value.attempt_number >= 1
    && value.attempt_number <= 2
    && outcomes.includes(value.outcome)
    && analysisStatuses.includes(value.analysis_status)
    && decisions.includes(value.validation_decision)
    && states.includes(value.current_state)
    && Number.isInteger(value.case_version)
    && value.case_version >= 2
    && typeof value.idempotent_replay === 'boolean'
    && typeof value.provider_called === 'boolean';
}

function isErrorBody(value) {
  return typeof value.error_code === 'string'
    && value.error_code.trim().length > 0
    && typeof value.message === 'string'
    && value.message.trim().length > 0
    && typeof value.retryable === 'boolean';
}

const responseStatus = Number($json.statusCode ?? $json.response_status);
const suppliedBody = $json.body ?? $json.response_body;
const rootBody = asObject(suppliedBody);
const candidates = distinctObjects([
  rootBody,
  asObject(rootBody?.body),
  asObject(rootBody?.data),
  asObject(rootBody?.response),
  asObject(rootBody?.json),
  asObject($json.data),
  asObject($json.response),
  asObject($json)
]);
const analysisBody = candidates.find(isAnalysisBody);
const errorBody = candidates.find(isErrorBody);

if (responseStatus === 200 && analysisBody) {
  return {
    json: {
      classification: 'FINALIZED',
      http_status: 200,
      analysis_run_id: analysisBody.analysis_run_id,
      case_reference: analysisBody.case_reference,
      attempt_number: analysisBody.attempt_number,
      outcome: analysisBody.outcome,
      analysis_status: analysisBody.analysis_status,
      validation_decision: analysisBody.validation_decision,
      current_state: analysisBody.current_state,
      case_version: analysisBody.case_version,
      idempotent_replay: analysisBody.idempotent_replay,
      provider_called: analysisBody.provider_called
    }
  };
}

if (
  responseStatus === 503
  && analysisBody
  && analysisBody.outcome === 'RETRYABLE_FAILURE'
) {
  return {
    json: {
      classification: 'RETRYABLE_FAILURE_RECORDED',
      http_status: 503,
      analysis_run_id: analysisBody.analysis_run_id,
      case_reference: analysisBody.case_reference,
      attempt_number: analysisBody.attempt_number,
      outcome: analysisBody.outcome,
      current_state: analysisBody.current_state,
      case_version: analysisBody.case_version,
      idempotent_replay: analysisBody.idempotent_replay,
      provider_called: analysisBody.provider_called
    }
  };
}

if (
  responseStatus === 409
  && errorBody?.error_code === 'ANALYSIS_IN_PROGRESS'
  && errorBody.retryable
) {
  return {
    json: {
      classification: 'IN_PROGRESS',
      http_status: 409,
      error_code: errorBody.error_code,
      retryable: true
    }
  };
}

if (
  !Number.isInteger(responseStatus)
  || responseStatus < 100
  || responseStatus > 599
  || (responseStatus >= 200 && responseStatus <= 299)
  || (!analysisBody && !errorBody)
) {
  return {
    json: {
      classification: 'INVALID_PRIMARY_RESPONSE',
      http_status: Number.isInteger(responseStatus) ? responseStatus : null,
      retryable: true
    }
  };
}

return {
  json: {
    classification: errorBody?.retryable
      ? 'RETRYABLE_CONTINUATION_FAILURE'
      : 'PERMANENT_CONTINUATION_FAILURE',
    http_status: responseStatus,
    error_code: errorBody?.error_code ?? `PRIMARY_HTTP_${responseStatus}`,
    retryable: errorBody?.retryable ?? false
  }
};
